// Она содержит конфигурацию, необходимую для обработки запросов на загрузку.
type UploadHandler struct {
	// UploadDir — директория, куда сохраняются загруженные файлы.
	UploadDir string
}

// NewUploadHandler создаёт новый экземпляр UploadHandler с указанной директорией для хранения файлов.
// Параметр uploadDir — абсолютный путь к директории, в которой будут сохраняться загруженные файлы.
// Возвращает указатель на новый UploadHandler и возможную ошибку, если директория не существует или не может быть создана.
func NewUploadHandler(uploadDir string) (*UploadHandler, error) {
	// Проверяем, существует ли директория. Если нет — пытаемся её создать.
	if _, err := os.Stat(uploadDir); os.IsNotExist(err) {
		if err := os.MkdirAll(uploadDir, 0755); err != nil {
			return nil, fmt.Errorf("не удалось создать директорию %s: %w", uploadDir, err)
		}
	}

	return &UploadHandler{
		UploadDir: uploadDir,
	}, nil
