/**
 * Ищет активного пользователя по логину.
 *
 * @param login Логин пользователя для поиска (регистр не учитывается).
 * @return Опциональный объект с найденным активным пользователем,
 *         или пустой Optional, если пользователь не найден, заблокирован или срок действия истек.
 */
public Optional<User> findActive(String login) {
    // Получаем поток из коллекции всех пользователей
    return users.stream()
        // Фильтруем пользователей, у которых логин совпадает с переданным (без учета регистра)
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // Фильтруем только активных пользователей:
        // 1. Пользователь не заблокирован (!u.isBlocked())
        // 2. Срок действия учетной записи еще не истек (u.getExpiresAt().isAfter(Instant.now()))
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // Возвращаем первого найденного пользователя, соответствующего всем условиям,
        // или пустой Optional, если таких пользователей нет
        .findFirst();
}
