/// <summary>
/// Выполняет асинхронное действие с повторными попытками при возникновении сетевых ошибок.
/// </summary>
/// <param name="action">Асинхронная функция, возвращающая целое число.</param>
/// <param name="attempts">Максимальное количество попыток выполнения действия.</param>
/// <returns>Результат выполнения действия (целое число).</returns>
/// <exception cref="InvalidOperationException">
/// Бросается, если все попытки исчерпаны и ни одна не завершилась успешно.
/// </exception>
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Цикл для выполнения действия с заданным количеством попыток
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Пытаемся выполнить действие и вернуть его результат
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Перехватываем только сетевые ошибки (HttpRequestException)
            // Условие when (i < attempts - 1) гарантирует, что задержка
            // не будет выполнена после последней неудачной попытки

            // Вычисляем экспоненциальную задержку:
            // 200 мс * 2^i (например: 200мс, 400мс, 800мс, 1600мс и т.д.)
            // Это помогает избежать перегрузки сервера при частых ошибках
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }

    // Если цикл завершился без возврата результата,
    // значит все попытки исчерпаны и действие не удалось выполнить
    throw new InvalidOperationException("unreachable");
}
