// Функция worker представляет собой функцию-работник (goroutine), которая
// обрабатывает задачи из канала jobs и отправляет результаты в канал results.
// Параметр wg — указатель на WaitGroup, используемый для синхронизации завершения всех работников.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
    // defer wg.Done() гарантирует, что после завершения работы данного работника
    // будет вызван метод Done() на WaitGroup, что позволит основному потоку
    // дождаться завершения всех работников перед выходом из программы.
    defer wg.Done()

    // Цикл for range jobs читает задачи из канала jobs до тех пор, пока канал не будет закрыт.
    // Каждый элемент канала (задача Job) последовательно извлекается в переменную j.
    for j := range jobs {
        // Вызываем функцию process для обработки текущей задачи j.
        // Она возвращает результат r и возможную ошибку err.
        r, err := process(j)

        // Если при обработке задачи произошла ошибка:
        if err != nil {
            // Логируем ошибку с указанием идентификатора задачи (j.ID) и текстом ошибки.
            log.Printf("job %d: %v", j.ID, err)
            // Пропускаем текущую задачу и переходим к следующей, не отправляя результат.
            continue
        }

        // Если обработка прошла успешно, отправляем результат r в канал results.
        // Это блокирующая операция: если буфер канала results заполнен,
        // работник будет ждать, пока другой горутин не заберет результат.
        results <- r
    }
}
