```typescript
/**
 * Создаёт функцию-обёртку, которая откладывает выполнение исходной функции
 * на указанное количество миллисекунд. Если функция вызывается повторно
 * до истечения таймера, предыдущий таймер отменяется и устанавливается новый.
 *
 * @param fn - Исходная функция, которую нужно «задебаунсить».
 * @param ms - Задержка в миллисекундах перед выполнением функции.
 * @returns Обёрнутая функция с той же сигнатурой, что и исходная.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора текущего таймера.
  // Изначально не задана (undefined), так как таймер ещё не создан.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и исходная.
  return (...args: Parameters<T>) => {
    // Если таймер уже существует (t не undefined), отменяем его.
    // Это обеспечивает «отложенное» выполнение: предыдущий вызов игнорируется,
    // если новый вызов происходит до истечения задержки.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер, который вызовет исходную функцию (fn)
    // с переданными аргументами (args) через ms миллисекунд.
    // Сохраняем идентификатор таймера в t, чтобы иметь возможность отменить его при следующем вызове.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

