type Counter struct {
	mu    sync.Mutex // Мьютекс для блокировки доступа к value
	value int        // Счётчик
}

// Метод Inc увеличивает счётчик с блокировкой
func (c *Counter) Inc() {
	c.mu.Lock()       // Блокируем доступ к value
	defer c.mu.Unlock() // Разблокируем при выходе из функции
	c.value++         // Безопасное увеличение
}

// Метод Value возвращает текущее значение счётчика с блокировкой
func (c *Counter) Value() int {
	c.mu.Lock()       // Блокируем доступ к value
	defer c.mu.Unlock() // Разблокируем при выходе из функции
	return c.value    // Возвращаем текущее значение
}

